mapper.select:
SELECT ABR_SN
  FROM ABUSE_REPORT
 WHERE RPRT_USR_SN = #{reporterUserSn}
   AND ABR_REF_TYPE_CD = #{referenceTypeCode}
   AND ABR_REF_SN = #{referenceSn}
 LIMIT 1

SELECT ABR_SN AS reportSn, ABR_REF_SN AS referenceSn, ABR_STATUS_CD AS statusCode FROM ABUSE_REPORT WHERE RPRT_USR_SN IS NOT NULL AND ABR_REF_TYPE_CD = #{referenceTypeCode} AND ABR_STATUS_CD IN (#{receivedStatusCode}, #{processingStatusCode}) AND ABR_REF_SN IN
#{referenceSn}
ORDER BY ABR_SN DESC

SELECT

  FROM ABUSE_REPORT ar
  LEFT JOIN CMM_CODE rt ON rt.CMM_CD = ar.ABR_TYPE_CD
  LEFT JOIN CMM_CODE st ON st.CMM_CD = ar.ABR_STATUS_CD
 WHERE ar.RPRT_USR_SN = #{reporterUserSn}
   AND ar.RSK_EVT_SN IS NULL


       AND ar.ABR_STATUS_CD IN ('ABRC0007', 'ABRC0008')


       AND ar.ABR_STATUS_CD = #{statusCode}


 ORDER BY ar.ABR_SN DESC
 LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
  FROM ABUSE_REPORT
 WHERE RPRT_USR_SN = #{reporterUserSn}
   AND RSK_EVT_SN IS NULL


       AND ABR_STATUS_CD IN ('ABRC0007', 'ABRC0008')


       AND ABR_STATUS_CD = #{statusCode}

SELECT
FROM ABUSE_REPORT
ORDER BY CASE ABR_STATUS_CD WHEN 'ABRC0005' THEN 0 WHEN 'ABRC0006' THEN 1 WHEN 'ABRC0007' THEN 2 WHEN 'ABRC0008' THEN 3 ELSE 4 END ASC, ABR_REG_DT DESC, ABR_SN DESC LIMIT #{size} OFFSET #{offset}

SELECT

FROM ABUSE_REPORT
WHERE RPTD_USR_SN = #{reportedUserSn}
ORDER BY ABR_REG_DT DESC, ABR_SN DESC
LIMIT #{limit}
